from .annotation_gtf import Annotation, NUM_STATES_V4, NUM_STATES_V4_SMORF_SPLIT
from .dataset import REVCOMP_CHANNELS

PHASE_CHANNELS = 3
VALID_V4_INP_SIZES = (12, 13, 15, 16)


def v4_input_size(*, sd_channel: bool = False, phase_channel: bool = False) -> int:
    return 12 + int(bool(sd_channel)) + (PHASE_CHANNELS if phase_channel else 0)


def phase_onehot(length: int) -> np.ndarray:
    """Per-base one-hot of ``position % 3`` on the full contig (genome frame)."""
    n = int(length)
    idx = np.arange(n, dtype=np.int64) % 3
    out = np.zeros((n, PHASE_CHANNELS), dtype=np.float32)
    if n:
        out[np.arange(n), idx] = 1.0
    return out


def merge_strand_features(
    sequence_matrix: np.ndarray,
    *,
    sd_channel: bool = False,
    phase_channel: bool = False,
) -> np.ndarray:
    """(L, 6) one-hot → 12 / 13 / 15 / 16 channels (SD and/or mod-3 phase)."""
    assert sequence_matrix.ndim == 2 and sequence_matrix.shape[1] == 6
    seq = np.asarray(sequence_matrix, dtype=np.float32)
    comp = seq[:, REVCOMP_CHANNELS].copy()
    parts = [np.concatenate([seq, comp], axis=1)]
    if sd_channel:
        from .sd_channel import normalized_sd_track_from_matrix

        sd = normalized_sd_track_from_matrix(sequence_matrix).reshape(-1, 1)
        parts.append(sd.astype(np.float32))
    if phase_channel:
        parts.append(phase_onehot(seq.shape[0]))
    return np.concatenate(parts, axis=1)


class ProkaDatasetV4(Dataset):
    """Sliding windows: x is (window, 12), y is (window, num_states) float multi-label."""

    def __init__(
        self,
        sequence_matrix: np.ndarray,
        labels_merged: np.ndarray,
        window_size: int = 9990,
        step: int = 4995,
        *,
        num_states: int = NUM_STATES_V4,
        sd_channel: bool = False,
        phase_channel: bool = False,
    ):
        if labels_merged.shape != (sequence_matrix.shape[0], num_states):
            raise ValueError(
                f"labels_merged must be (L,{num_states}), got {labels_merged.shape}"
            )
        self.num_states = int(num_states)
        self.x = merge_strand_features(
            sequence_matrix, sd_channel=sd_channel, phase_channel=phase_channel,
        )
        self.y = np.asarray(labels_merged, dtype=np.float32)
        self.window_size = int(window_size)
        self.step = int(step)
        self.seq_len = self.x.shape[0]
        self.starts = np.arange(
            0, max(0, self.seq_len - self.window_size + 1), self.step, dtype=np.int64
        )

    def __len__(self) -> int:
        return len(self.starts)

    def __getitem__(self, idx: int):
        start = int(self.starts[idx])
        end = start + self.window_size
        return (
            torch.from_numpy(self.x[start:end]),
            torch.from_numpy(self.y[start:end]),
        )


