class ProkaContigV4Aux:
    """Full-contig tensors for smORF-aware window sampling."""

    def __init__(
        self,
        sequence_matrix: np.ndarray,
        labels_merged: np.ndarray,
        smorf_mask: np.ndarray,
        window_size: int = 9990,
        *,
        sd_channel: bool = False,
        phase_channel: bool = False,
    ):
        if labels_merged.shape != (sequence_matrix.shape[0], NUM_STATES_V4):
            raise ValueError(
                f"labels_merged must be (L,{NUM_STATES_V4}), got {labels_merged.shape}"
            )
        if smorf_mask.shape != (sequence_matrix.shape[0],):
            raise ValueError(f"smorf_mask must be (L,), got {smorf_mask.shape}")
        self.x = merge_strand_features(
            sequence_matrix, sd_channel=sd_channel, phase_channel=phase_channel,
        )
        self.y11 = np.asarray(labels_merged, dtype=np.float32)
        self.y_aux = smorf_mask.reshape(-1, 1).astype(np.float32)
        self.window_size = int(window_size)
        self.seq_len = self.x.shape[0]

    def slice_window(self, start: int) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        end = start + self.window_size
        if start < 0 or end > self.seq_len:
            raise IndexError(f"window [{start},{end}) out of range for length {self.seq_len}")
        return (
            self.x[start:end],
            self.y11[start:end],
            self.y_aux[start:end],
        )

    def bucket_starts(self, *, step: int = 1) -> dict[str, list[int]]:
        """Classify valid window starts into smorf / long_only / igr_only."""
        w = self.window_size
        buckets: dict[str, list[int]] = {"smorf": [], "long_only": [], "igr_only": []}
        if self.seq_len < w:
            return buckets
        stride = max(1, int(step))
        for start in range(0, self.seq_len - w + 1, stride):
            end = start + w
            aux = self.y_aux[start:end, 0]
            coding = self.y11[start:end, 1:11].sum(axis=1) > 0
            if aux.sum() > 0:
                buckets["smorf"].append(start)
            elif coding.sum() > 0:
                buckets["long_only"].append(start)
            else:
                buckets["igr_only"].append(start)
        return buckets


