class SmorfBalancedWindowDataset(Dataset):
    """Sample windows with smORF / long / IGR fractions and smORF jitter."""

    BUCKETS = ("smorf", "long_only", "igr_only")

    def __init__(
        self,
        contigs: list[ProkaContigV4Aux],
        *,
        window_fractions: tuple[float, float, float] = (0.5, 0.25, 0.25),
        seed: int = 1,
        bucket_step: int = 4995,
        bucket_cache: list[dict[str, list[int]]] | None = None,
    ):
        if not contigs:
            raise ValueError("contigs cannot be empty")
        if bucket_cache is not None and len(bucket_cache) != len(contigs):
            raise ValueError("bucket_cache length must match contigs")
        fr = window_fractions
        if len(fr) != 3 or any(f < 0 for f in fr) or sum(fr) <= 0:
            raise ValueError(f"invalid window_fractions: {window_fractions}")
        self.contigs = contigs
        self.frac_smorf, self.frac_long, self.frac_igr = fr
        self.seed = int(seed)
        self._epoch = 0
        self._bucket_starts: dict[str, list[tuple[int, int]]] = {
            b: [] for b in self.BUCKETS
        }
        stride = max(1, int(bucket_step))
        for ci, contig in enumerate(contigs):
            local = (
                bucket_cache[ci]
                if bucket_cache is not None
                else contig.bucket_starts(step=stride)
            )
            for bucket in self.BUCKETS:
                for start in local[bucket]:
                    self._bucket_starts[bucket].append((ci, start))
        if not any(self._bucket_starts[b] for b in self.BUCKETS):
            raise ValueError("no valid windows in SmorfBalancedWindowDataset")
        self._fallback_bucket = max(
            self.BUCKETS,
            key=lambda b: len(self._bucket_starts[b]),
        )

    def __len__(self) -> int:
        return sum(len(v) for v in self._bucket_starts.values())

    def _pick_bucket(self, rng: random.Random) -> str:
        r = rng.random()
        if r < self.frac_smorf:
            bucket = "smorf"
        elif r < self.frac_smorf + self.frac_long:
            bucket = "long_only"
        else:
            bucket = "igr_only"
        if not self._bucket_starts[bucket]:
            bucket = self._fallback_bucket
        return bucket

    def sample_window(self, rng: random.Random) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        bucket = self._pick_bucket(rng)
        ci, start = rng.choice(self._bucket_starts[bucket])
        x, y11, y_aux = self.contigs[ci].slice_window(start)
        return torch.from_numpy(x), torch.from_numpy(y11), torch.from_numpy(y_aux)

    def __getitem__(self, idx: int):
        rng = random.Random(self.seed + self._epoch * 999_983 + int(idx) * 1_000_003)
        return self.sample_window(rng)

    def set_epoch(self, epoch: int) -> None:
        self._epoch = int(epoch)


