def make_proka_contig_v4_smorf_split(
    genome,
    annotation: Annotation,
    seq_name: str,
    *,
    window_size: int = 9990,
    smorf_max_nt: int = 300,
    length_weight_ref_nt: int = 300,
    length_weight_min: float = 1.0,
    length_weight_max: float = 5.0,
    enable_length_weights: bool = True,
    sd_channel: bool = False,
    phase_channel: bool = False,
) -> ProkaContigV4SmorfSplit:
    seq_matrix = genome.get_full_encoded_sequence(seq_name)
    seq_len = seq_matrix.shape[0]
    y17 = annotation.get_merged_multilabel_labels_smorf_split_frames(
        seq_name, seq_len, max_nt=smorf_max_nt,
    )
    smorf_mask = annotation.get_smorf_binary_mask(seq_name, seq_len, max_nt=smorf_max_nt)
    if enable_length_weights:
        length_weights = annotation.get_orf_length_weight_mask(
            seq_name,
            seq_len,
            ref_nt=length_weight_ref_nt,
            min_weight=length_weight_min,
            max_weight=length_weight_max,
        )
    else:
        length_weights = np.ones(seq_len, dtype=np.float32)
    return ProkaContigV4SmorfSplit(
        sequence_matrix=seq_matrix,
        labels_smorf_split=y17,
        smorf_mask=smorf_mask,
        length_weights=length_weights,
        window_size=window_size,
        sd_channel=sd_channel,
        phase_channel=phase_channel,
    )
